INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (1,1,'🐛🍎','星期一的早晨，一条小毛毛虫从蛋里钻了出来。它好饿好饿，去找东西吃。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (1,2,'🐛🍐','星期一吃了一个苹果还是好饿，星期二吃了两个梨还是好饿。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (1,3,'🐛🍓','星期三吃了三个草莓，星期四吃了四个橘子，越来越胖了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (1,4,'🐛🍰','星期五到星期日吃了好多东西：蛋糕冰淇淋……肚子好疼啊！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (1,5,'🐛🌿','吃了一片绿叶肚子舒服了，变成了一条又胖又大的毛毛虫。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (1,6,'🦋🌸','毛毛虫造了一个茧，咬破茧钻出来——变成了一只美丽的蝴蝶！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (2,1,'🐻👀','棕色的熊你在看什么？我看见一只红色的鸟在看我。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (2,2,'🐦👀','红色的鸟你在看什么？我看见一只黄色的鸭子在看我。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (2,3,'🦆👀','黄色的鸭子你在看什么？我看见一匹蓝色的马在看我。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (2,4,'🐴👀','蓝色的马你在看什么？我看见一只绿色的青蛙在看我。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (2,5,'🐸👀','绿色的青蛙你在看什么？我看见一只紫色的猫在看我。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (2,6,'🐱👀','紫色的猫你在看什么？我看见好多小朋友在看我！一起做游戏吧！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (3,1,'🔵🏠','这是小蓝，最好的朋友是小黄。他们最喜欢一起玩藏猫猫。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (3,2,'🔵🟡','有一天他们紧紧抱在一起——变成了小绿！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (3,3,'💚😢','小蓝的爸爸妈妈说：你不是我们的小蓝！小黄的爸爸妈妈也说：你不是我们的小黄！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (3,4,'🔵💧','他们伤心地哭，蓝色和黄色的眼泪流了出来，终于变回了自己！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (3,5,'👨‍👩‍👦🤗','爸爸妈妈高兴地抱住了他们。友谊是最美的颜色！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (3,6,'🌈✨','不同的颜色融合在一起能变出新的美丽，朋友也是这样！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (4,1,'🍎🐜','首先要有一个苹果，苹果吸引了两条毛毛虫，毛毛虫引来了一只小鸟。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (4,2,'🐛🐦','小鸟被猎狗追着跑，猎狗后面跟着一只大猫。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (4,3,'🐕🐈','大猫碰到了山羊，山羊遇到了牛，牛看到了绵羊……越来越多啦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (4,4,'🐄🐑','绵羊后面跟着牧羊人，牧羊人碰到大卡车。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (4,5,'🚛🍎','卡车里装着好多苹果！一个小小的苹果变成了一车苹果！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (4,6,'🎉✨','小小的开始可能带来大大的惊喜，每个事物都是有关联的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (5,1,'🚌🏠','巴士到站了！做面包的叔叔下车去面包店上班。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (5,2,'🚌🏗️','巴士又到站了！建筑工人下车去盖房子。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (5,3,'🚌🎨','巴士又到站了！画画的大姐姐下车去画室。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (5,4,'🚌📚','巴士又到站了！小朋友们下车去上学。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (5,5,'🚌🏥','巴士又到站了！医生下车去医院照顾病人。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (5,6,'🚌🌙','最后一站到了大家回到温暖的家，明天巴士还会来接大家！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (6,1,'🐍🍎','好饿的小蛇发现了一个苹果，啊呜——咕嘟！吞了下去。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (6,2,'🐍🍌','又发现了一根香蕉，啊呜——咕嘟！肚子变成香蕉形状！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (6,3,'🐍🍇','又发现了一串葡萄，啊呜——咕嘟！肚子变成葡萄的样子！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (6,4,'🐍🎂','又发现了一个蛋糕，啊呜——咕嘟！肚子变成蛋糕形状！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (6,5,'🐍🌲','又发现了一棵苹果树，啊呜——咕嘟！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (6,6,'🐍😊','小蛇把整棵树都吞了！终于吃饱了开心地回家啦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (7,1,'⭕🐱','圆圆的洞洞里藏着什么？猜猜看——是猫咪的耳朵！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (7,2,'⭕🐶','翻一翻是小狗的鼻子，方方的洞洞又藏着什么？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (7,3,'⭕🐰','是兔子的长耳朵！三角形的洞洞又是谁的？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (7,4,'⭕🐘','是大象的大耳朵！挖孔绘本真好玩，每个形状都有惊喜。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (7,5,'⭕🐻','心形的洞洞藏着小熊的脚印！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (7,6,'⭕🎉','所有洞洞都翻完了！你记住了哪些形状和动物？再翻一次吧！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (8,1,'⚪👆','按一下这个黄色的圆点，翻到下一页看看会发生什么？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (8,2,'⚪⚪','哇变成了两个！再按一下呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (8,3,'⚪⚪⚪','三个啦！现在摸一摸左边那个圆点。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (8,4,'🔴🔵🟡','变成了红蓝黄三种颜色！摇一摇书试试。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (8,5,'🔴🔵🟡🌟','圆点变大了变多了，好像在跳舞！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (8,6,'🌈✨','按下最后一个黄点……又回到开始！你真是个魔法师！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (9,1,'🔴👆','把手放在红色圆上数到三——变！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (9,2,'🟠✨','红色变成了橙色！蓝色和黄色碰在一起呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (9,3,'🟢✨','变成了绿色！红色手和蓝色手握在一起呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (9,4,'🟣✨','变成了紫色！红色加黄色会变什么？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (9,5,'🟠🎉','橙色！三种颜色变出了好多新颜色！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (9,6,'🌈🎨','红黄蓝是基本色，能变出世界上所有的颜色！你也来试试吧！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (10,1,'🐰🌸','小兔比利的耳朵毛茸茸的，摸一摸好柔软！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (10,2,'🐰🌿','花园里有柔软的花瓣和粗糙的树皮，摸起来不一样！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (10,3,'🐰🐛','叶子上有只小虫子，滑溜溜的摸起来凉凉的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (10,4,'🐰🪶','小鸟的羽毛好轻好软像棉花一样。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (10,5,'🐰🌰','松果硬硬的刺刺的，不同东西摸起来感觉真不一样！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (10,6,'🐰❤️','通过触摸发现了好多有趣的东西！你也来摸摸看吧！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (11,1,'❓👀','我有两只长耳朵一条短尾巴，猜猜我是谁？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (11,2,'❓🐰','是兔子！再猜一个：我背着硬硬的壳走路慢慢的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (11,3,'❓🐢','是乌龟！再猜：我有长鼻子大耳朵。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (11,4,'❓🐘','是象！猜谜语真好玩！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (11,5,'❓🏊','我在水里游得最快尾巴像扇子，猜猜我是谁？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (11,6,'❓🐟','是鱼！你来出个谜语让大家猜吧！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (12,1,'📦🐘','我写信给动物园请他们送我一只宠物，大箱子来了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (12,2,'📦🦒','打开一看是长颈鹿！太高了养不了，退回去吧。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (12,3,'📦🐒','第二个是猴子！太调皮了，退回去吧。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (12,4,'📦🦁','第三个是狮子！太凶了，退回去吧。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (12,5,'📦🐸','第四个是青蛙！太爱跳了，退回去吧。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (12,6,'📦🐶❤️','最后是只小狗！不凶不闹太完美了！亲爱的动物园谢谢！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (13,1,'🐟🏠','小金鱼从鱼缸里逃走了！它藏到哪儿去了？找找看！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (13,2,'🐟🌸','小金鱼藏在花丛中假装自己是一朵花！可是眼睛露馅了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (13,3,'🐟🍓','这次藏在草莓堆里假装自己是一颗草莓。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (13,4,'🐟🍬','又跑到糖果罐里去了！你能找到它吗？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (13,5,'🐟🎨','藏在画里了混在好多圆圈中间，更难找了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (13,6,'🐟🐟🐟','终于找到了！它跳进大鱼缸里和好多小伙伴在一起，再也不逃了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (14,1,'🐷🥞','小猪做了好大的饼睡着了，醒来一看大饼被咬了一口！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (14,2,'🐦🥞','小鸟咬了一口：不是我，我咬的印子小小的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (14,3,'🐰🥞','兔子咬了一口：不是我，我咬的是两颗门牙的印子。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (14,4,'🦊🥞','狐狸咬了一口：不是我，我的牙印更大。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (14,5,'🐘🥞','大象咬了一口：不是我，我的牙印最大最大！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (14,6,'🐷😋','小猪自己也咬了一口——这个牙印和大饼上的一模一样！原来是自己梦游时咬的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (15,1,'🔴🟡🔵','欢迎来到颜色国！有红色的城堡、黄色的花园和蓝色的湖泊。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (15,2,'🔴🌈','红色是热情的颜色像火一样温暖！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (15,3,'🟡☀️','黄色是快乐的颜色像太阳一样明亮！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (15,4,'🔵🌊','蓝色是安静的颜色像大海一样深邃！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (15,5,'🟢🌲','绿色是生命的颜色，是黄和蓝混合而成的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (15,6,'🎨✨','颜色国的秘密：所有颜色都是好朋友，混合在一起就能变出最美妙的色彩！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (16,1,'🐰❤️','小兔子问大兔子：猜猜我有多爱你？我猜不到。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (16,2,'🐰👐','小兔子张开双臂：我爱你有这么多！大兔子的手臂更长：我爱你有更多。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (16,3,'🐰⬆️','小兔子把手举得高高：我爱你到手指头那么高！大兔子举得更高！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (16,4,'🐰🌊','小兔子跳起来：我爱你像跳得那么高！大兔子跳得更高！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (16,5,'🐰🌙','小兔子说：我爱你一直到月亮那里。大兔子微笑了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (16,6,'🐰🌙❤️','大兔子轻声说：我爱你一直到月亮那里再从月亮回到这里来。爱是无穷无尽的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (17,1,'👨👦','这是我爸爸他真的很棒！他什么都不怕。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (17,2,'👨🏃','爸爸跑得像赛马一样快，游得像鱼一样快，强壮得像大猩猩！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (17,3,'👨🧘','爸爸像猫头鹰一样聪明，有时候也做些傻事。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (17,4,'👨🎵','爸爸是伟大的舞蹈家，也是了不起的歌唱家。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (17,5,'👨⚽','爸爸踢足球技术一流，还经常逗我哈哈大笑。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (17,6,'👨❤️👦','我爱我爸爸，而且他也爱我，永远爱我！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (18,1,'👩👧','这是我妈妈她真的很棒！她是了不起的厨师和杂技演员。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (18,2,'👩🎨','妈妈是神奇的画家，也是世界上最强壮的女人！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (18,3,'👩🌻','妈妈的花园开满了花，歌声像天使一样甜美。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (18,4,'👩🦁','妈妈吼起来像狮子一样凶猛，温柔起来像小猫一样柔软。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (18,5,'👩🦸','妈妈像蝴蝶一样美丽，像沙发一样舒适。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (18,6,'👩❤️👧','我爱我妈妈，而且她也爱我，永远爱我！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (19,1,'🐰🏃','小兔子说我要跑走啦！兔妈妈说如果你跑走了我就去追你，因为你是我的小宝贝。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (19,2,'🐟🎣','小兔子说我要变成小鱼，兔妈妈说那我就变成渔夫来抓你。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (19,3,'🧗🧗‍♀️','小兔子说我要变成高山的石头，兔妈妈说那我就变成爬山的人找到你。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (19,4,'🌸🥀','小兔子说我要变成花园里的花，兔妈妈说那我就变成园丁来照顾你。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (19,5,'🐦🌳','小兔子说我要变成小鸟飞走，兔妈妈说那我就变成树让你飞回家。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (19,6,'🐰🏠❤️','小兔子说我还是待在家里做你的小宝贝吧。妈妈的爱永远都在。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (20,1,'👴✂️','爷爷给约瑟做了一条奇妙的毯子，约瑟好喜欢。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (20,2,'👴✂️','毯子旧了，约瑟说爷爷一定有办法！爷爷把毯子改成了外套。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (20,3,'👴✂️','外套旧了改成领带，领带旧了改成手帕。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (20,4,'👴✂️','手帕旧了改成纽扣。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (20,5,'👴😢','纽扣也丢了！这次连爷爷也没办法了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (20,6,'👦📝✨','约瑟写下了这个故事。只要有爱什么都能变成美好的回忆！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (21,1,'🐒😊','小猩猩看到大象妈妈抱着小象，好温暖。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (21,2,'🦎❤️','蜥蜴妈妈抱着小蜥蜴，蛇妈妈抱着小蛇……大家都在抱抱。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (21,3,'🐒😢','小猩猩也好想要抱抱，可是妈妈在哪儿呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (21,4,'🐘🐒','大象妈妈用鼻子把小猩猩举起来，带它去找妈妈。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (21,5,'🐒🤗❤️','猩猩妈妈来了！小猩猩扑进妈妈怀里紧紧抱在一起。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (21,6,'🎉🤗','所有动物都开心地抱在一起。抱抱是世界上最温暖的语言！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (22,1,'🐻🌙','小熊喜欢月亮想送月亮一份生日礼物。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (22,2,'🐻⛰️','小熊爬上最高的山喊你好！月亮也回答你好！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (22,3,'🐻🎂','小熊问月亮的生日，月亮回答的竟然是同一天！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (22,4,'🐻🎩','月亮说想要一顶帽子，小熊就去买了帽子。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (22,5,'🐻🎈','帽子被风吹走了，他们互相说对不起还是好朋友。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (22,6,'🐻🌙❤️','虽然隔着那么远他们的心却很近，生日快乐！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (23,1,'🐱🐟','猫养了一条小鱼每天喂它面包，小鱼越长越大。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (23,2,'🐱🐟🌊','鱼缸装不下小鱼了，猫说你应该回到大海里去。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (23,3,'🐱😢','猫把小鱼放回大海，每天坐在海边等。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (23,4,'🐟🐠','小鱼在海里自由自在地游但没忘记猫。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (23,5,'🐟😊','有一天小鱼从海里跳了出来！它回来了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (23,6,'🐱🐟❤️','真正的爱是给对方自由却依然彼此牵挂。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (24,1,'🐊🦒','鳄鱼爱上了长颈鹿，可是一个太矮一个太高怎么见面呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (24,2,'🐊🪜','鳄鱼踩高跷摔了，在桥上表演特技也没被注意到。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (24,3,'🐊🎈','用绳子弹到自己却弹进了水里，真倒霉！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (24,4,'🐊🦒💥','终于他们撞在了一起四目相对。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (24,5,'🐊🦒😊','他们发现彼此有很多共同点好开心！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (24,6,'🐊🦒❤️','差异也能变成最美的风景，爱情就是如此奇妙！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (25,1,'🌸🌈','春天来了一朵彩虹色的花开放了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (25,2,'🐜🌸','小蚂蚁想过水洼，彩虹花送它一片橙色花瓣当小船。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (25,3,'🦎🌸','小蜥蜴要参加宴会，彩虹花送它一片红色花瓣当披风。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (25,4,'🐭🌸','小老鼠太热了，彩虹花送它一片蓝色花瓣当扇子。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (25,5,'🐦🌸','小鸟要送女儿礼物，彩虹花送它一片黄色花瓣。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (25,6,'🌈🌸❤️','冬天花枯萎了但春天新的彩虹花再次绽放！分享的爱永不消失。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (26,1,'🦖🥚','霸王龙要吃小甲龙，小甲龙却抱住它：爸爸！你看起来好像很好吃！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (26,2,'🦖😊','很好吃竟然成了小甲龙的名字！霸王龙只好当了爸爸。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (26,3,'🦖🌿','霸王龙教很好吃吃红果子，很好吃说我也要像爸爸一样强壮！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (26,4,'🦖💪','很好吃很努力地学，霸王龙发现自己越来越喜欢这个小家伙。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (26,5,'🦖🦎','有一天很好吃勇敢地保护爸爸，霸王龙好感动。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (26,6,'🦖🥹❤️','霸王龙把很好吃送回了甲龙爸妈身边。虽然舍不得但这才是最好的爱。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (27,1,'🦖🦖','小翼龙的爸爸教它飞翔妈妈教它善良，它都记住了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (27,2,'🌋🦖','火山爆发霸王龙从悬崖摔下来受伤了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (27,3,'🦖😢','小翼龙决定照顾受伤的霸王龙假装自己也是霸王龙。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (27,4,'🦖🍎','小翼龙每天给霸王龙找食物喂水，霸王龙渐渐好起来。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (27,5,'🦖🦖😊','霸王龙眼睛好了！小翼龙害怕地飞走了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (27,6,'🦖❤️','霸王龙望着飞走的小翼龙说谢谢你是我的朋友。善良让世界温暖。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (28,1,'🦖🥚','慈母龙妈妈发现了一个蛋带回家孵了出来。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (28,2,'🦖🌿','小慈母龙和小霸王龙一起长大是最好的兄弟。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (28,3,'🦖🦖','可是小霸王龙越长越不像慈母龙……');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (28,4,'🦖🥹','小霸王龙发现了真相很伤心：我不是你们的孩子吗？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (28,5,'🦖❤️','慈母龙妈妈紧紧抱住它：不管你是谁你永远永远是我的宝贝！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (28,6,'🦖❤️🌙','小霸王龙悄悄采了红果子放在家门口。虽然离开了但爱永不消失。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (29,1,'🦖😬','霸王龙总是欺负小动物大家都很怕它。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (29,2,'🦖🌊','有一天霸王龙掉进海里薄片龙救了它。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (29,3,'🦖😊','薄片龙说你真好！从来没人对霸王龙说过这样的话。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (29,4,'🦖🐚','它们成了好朋友每天在海边玩耍捡贝壳。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (29,5,'🦖🥹','霸王龙不再欺负别人了学会了关心和帮助。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (29,6,'🦖❤️','一句你真好改变了霸王龙。友善的语言有改变世界的力量！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (30,1,'🦖🗣️','霸王龙学会了说我爱你发现说出来并不难。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (30,2,'🦖🌸','对花说我爱你花好像开得更艳了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (30,3,'🦖🌿','对小草说我爱你小草好像更绿了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (30,4,'🦖☀️','对太阳说我爱你阳光好像更温暖了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (30,5,'🦖🦖','对朋友说我爱你朋友开心地笑了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (30,6,'🦖❤️✨','爱要大声说出来！一句我爱你能让世界更美好。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (31,1,'🦖🏝️','霸王龙被困在小岛上好孤单好害怕。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (31,2,'🦖🦖','这时另一只恐龙出现了它们一起找食物躲避危险。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (31,3,'🦖🤝','互相帮助互相鼓励有了朋友就不觉得孤单了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (31,4,'🦖😊','霸王龙说遇到你真好！朋友说遇到你也真好！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (31,5,'🦖🌅','一起看日出日落数星星有朋友就不怕困难。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (31,6,'🦖❤️✨','遇到一个好朋友是最幸运的事，珍惜每个人吧！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (32,1,'🦖🦖🦖','几只恐龙争着说爸爸最爱的是我！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (32,2,'🦖🏆','它们比谁跑得快吃得多最听话都想知道谁最受宠。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (32,3,'🦖🤔','爸爸说你们每一个都是我最爱的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (32,4,'🦖❤️','可是小恐龙们还是不依不饶：你最爱谁？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (32,5,'🦖🤗','爸爸抱住所有小恐龙：每个孩子都是独一无二的我对你们的爱一样多！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (32,6,'🦖❤️✨','爱不会因为分享而变少。每个孩子都是最特别的宝贝！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (33,1,'👦😠','霍斯今天很不开心！踩了花、吼叫、趴在地上不起来。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (33,2,'👩🍳','妈妈说我们来煮生气汤吧！她对着锅大喊大叫。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (33,3,'👦🔥','霍斯也对着锅大吼！敲打锅子吐舌头喷火！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (33,4,'👦💨','妈妈和霍斯一起对着汤尖叫打嗝吐舌头，汤冒出了好多泡泡！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (33,5,'👦😊','渐渐地霍斯不生气了笑了！坏心情都蒸发了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (33,6,'🍲❤️','每个人都会生气找个安全方式发泄出来心情好了就没事了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (34,1,'🎨😵','小怪兽心里乱糟糟的所有情绪缠在了一起。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (34,2,'😠🔴','红色是生气象火焰一样燃烧。你生气时什么感觉？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (34,3,'😊🟡','黄色是快乐像太阳一样明亮。快乐时会笑会跳！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (34,4,'😢🔵','蓝色是忧伤像下雨的天空。难过时哭一哭也没关系。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (34,5,'😌🟢','绿色是平静像微风吹过树叶。安静时心里好舒服。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (34,6,'😨⚫','黑色是害怕像黑暗中看不清前方。情绪来了又会走你只需要认识它们。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (35,1,'👧😠','菲菲正在玩拼图姐姐抢走了大猩猩！妈妈还帮姐姐。菲菲气坏了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (35,2,'🌋👧','菲菲气得像要爆发的火山！踢打尖叫咆哮！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (35,3,'👧🏃','菲菲跑出了门跑到了一棵大榉树下。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (35,4,'🌳🐦','她爬上树看到广阔天空听到鸟叫感受到微风。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (35,5,'🌊😊','看着远处水面心情慢慢平静下来。世界好宽广好美丽。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (35,6,'👧🏠❤️','菲菲回到家家人都在等她。生气是正常的但平静的感觉真好。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (36,1,'🐰😠','小兔子说我讨厌妈妈！她总催我起床不让我看电视逼我吃青菜！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (36,2,'🐰😤','最讨厌的是妈妈星期天总睡懒觉不陪我玩！我要离家出走！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (36,3,'🐰🎒','小兔子收拾行李准备出门可是帽子还没戴好。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (36,4,'🐰🤔','小兔子又回来了：我走了以后你找不到我怎么办？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (36,5,'🐰❤️','妈妈笑了紧紧抱住小兔子。小兔子也抱住了妈妈。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (36,6,'🐰😊','嘴上说讨厌心里却满满都是爱。妈妈永远是最爱你的人。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (37,1,'🦖👶','当我还是一个小小的蛋时妈妈就爱着我。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (37,2,'🦖🌱','当我破壳而出妈妈抱着我说我会一直爱你。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (37,3,'🦖🏃','当我跑得比妈妈还快时妈妈笑着说我会一直爱你。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (37,4,'🦖🌊','当我遇到困难害怕时妈妈陪着我我会一直爱你。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (37,5,'🦖🏔️','当我长大离开家去看世界妈妈在家等我我会一直爱你。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (37,6,'🦖❤️✨','不管去到哪里妈妈的爱从未改变——一直爱你永远爱你。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (38,1,'👩👧','那一天我数着你的手指轻轻亲吻它们，你那么小那么柔软。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (38,2,'👧🌊','有一天你跑向大海浪花打湿了裙子，你在阳光下笑得那么美。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (38,3,'👧📚','有一天你背上行李离开家，我看着你的背影又骄傲又心酸。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (38,4,'👩🏔️','有一天我看着你攀上高山走出比我更远的路。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (38,5,'👩🌙','有一天你也会牵着小小的手给她讲我曾经讲给你的故事。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (38,6,'👩❤️✨','有一天你会明白所有的爱都在这里——从第一次抱你那天起到永远。');